<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); DB::setDefaultConnection('mysql'); config(['database.connections.mysql.database' => 'aeroclu_api-crm']); DB::purge('mysql'); DB::reconnect('mysql'); $idCurso = 128; $matriculas = DB::table('matriculas')->leftJoin('posts as sit', 'matriculas.situacao_id', '=', 'sit.ID')->where('matriculas.id_curso', $idCurso)->where(function ($q) { $q->whereNull('matriculas.excluido')->orWhere('matriculas.excluido', '!=', 's'); })->where(function ($q) { $q->whereNull('matriculas.deletado')->orWhere('matriculas.deletado', '!=', 's'); })->select('matriculas.orc', 'sit.post_name as situacao_slug')->get(); $counts = []; foreach ($matriculas as $m) { if(!$m->orc) continue; $orc = is_string($m->orc) ? json_decode($m->orc, true) : $m->orc; if(!is_array($orc) || empty($orc['modulos'])) continue; $primeiro = is_array($orc['modulos']) ? reset($orc['modulos']) : null; if(!$primeiro || empty($primeiro['id'])) continue; $pid = (string)$primeiro['id']; if(!isset($counts[$pid])) $counts[$pid] = ['total' => 0, 'mat' => 0, 'int' => 0]; $counts[$pid]['total']++; if($m->situacao_slug === 'mat') $counts[$pid]['mat']++; if($m->situacao_slug === 'int') $counts[$pid]['int']++; } echo json_encode($counts);
